type Page = 'Overview'|'Issues'|'Assets'|'Notifications'|'Public ledger'|'Audit trail'|'About Noro'
const fmt = (date: string) => new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short'}).format(new Date(date))
const agoText = (date: string) => { const days = Math.max(0,Math.floor((Date.now()-new Date(date).getTime())/86400000)); return days===0?'Today':`${days} day${days===1?'':'s'} ago` }
const initials = (s: string) => s.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()
const statusClass = (s: string) => s.toLowerCase().replaceAll(' ','-')

function Brand({small=false}:{small?:boolean}) { return <div className="brand"><span className="brand-mark">N</span>{!small&&<span className="brand-name">noro<span className="brand-dot">.</span></span>}</div> }
function Status({value}:{value:string}) { const icon = value.includes('Verified closed')||value==='Verified'?<Check size={13}/>:value.includes('claimed')||value.includes('pending')?<Clock3 size={13}/>:value==='Reopened'?<ArrowDownRight size={13}/>:<Radio size={13}/>; return <span className={`status ${statusClass(value)}`}>{icon}{value}</span> }

function WorkspaceApp({initialRole='Public'}:{initialRole?:Role}) {
  const [store,setStore]=useState<Store>(loadStore)
  const role=initialRole
  const [persona]=useState(()=>{try{return JSON.parse(sessionStorage.getItem('noro-demo-identity')??'{}') as {id?:string;name?:string;role?:string;sub?:string}}catch{return {}}})
  const [page,setPage]=useState<Page>('Overview')
  const [activeIssue,setActiveIssue]=useState<string|null>(null)
  const [query,setQuery]=useState('')
  const [filter,setFilter]=useState('All statuses')
  const [menuOpen,setMenuOpen]=useState(false)
  const [modal,setModal]=useState<'report'|'location'|null>(null)
  const [locationIssueId,setLocationIssueId]=useState<string|null>(null)
  const [correctedLocation,setCorrectedLocation]=useState<ConfirmedLocation|null>(null)
  const [correctedAssetId,setCorrectedAssetId]=useState('')
  const [locationReason,setLocationReason]=useState('')
  const [toast,setToast]=useState('')
  const [online,setOnline]=useState(navigator.onLine)
  useEffect(()=>saveStore(store),[store])
  useEffect(()=>{const on=()=>setOnline(navigator.onLine);window.addEventListener('online',on);window.addEventListener('offline',on);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',on)}},[])
  useEffect(()=>{if(!modal)return;const dialog=document.querySelector<HTMLElement>('[role="dialog"]');if(!dialog)return;const previous=document.activeElement as HTMLElement|null;const focusable=()=>Array.from(dialog.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[href],[tabindex]:not([tabindex="-1"])'));requestAnimationFrame(()=>focusable()[0]?.focus());const onKeyDown=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();setModal(null);return}if(event.key!=='Tab')return;const items=focusable();if(!items.length)return;const first=items[0]!,last=items[items.length-1]!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}};document.addEventListener('keydown',onKeyDown);return()=>{document.removeEventListener('keydown',onKeyDown);previous?.focus()}},[modal])
  const issue=store.issues.find(i=>i.id===activeIssue)
  const allowedPages:Page[]=role==='Manager'?['Overview','Issues','Assets','Notifications','Public ledger','Audit trail','About Noro']:role==='Contractor'?['Overview','Issues','Notifications','Public ledger','About Noro']:role==='Verifier'?['Overview','Issues','Assets','Notifications','Public ledger','About Noro']:['Overview','Issues','Assets','Notifications','Public ledger','About Noro']
  const roleIssues=store.issues.filter(i=>(role!=='Citizen'||i.reporterId===persona.id||['Asha R.','Asha Rao'].includes(i.reporter))&&(role!=='Contractor'||i.assigneeId===persona.id)&&(role!=='Verifier'||['Under verification','Repair claimed','Verification pending','Verified closed','Reopened'].includes(i.status)))
  const visibleIssues=useMemo(()=>roleIssues.filter(i=>(filter==='All statuses'||i.status===filter)&&(i.title.toLowerCase().includes(query.toLowerCase())||i.id.toLowerCase().includes(query.toLowerCase())||assetFor(store,i).name.toLowerCase().includes(query.toLowerCase()))),[store,role,filter,query,persona.id])
  const metrics={assets:store.assets.length,open:roleIssues.filter(i=>!['Verified closed','Cancelled','Duplicate'].includes(i.status)).length,claimed:roleIssues.reduce((count,i)=>count+i.history.filter(event=>event.label==='Repair claimed').length,0),verified:roleIssues.filter(i=>i.status==='Verified closed').length,reopened:roleIssues.filter(i=>i.status==='Reopened').length,pending:roleIssues.filter(i=>i.status==='Verification pending').length}
  const flash=(text:string)=>{setToast(text);window.setTimeout(()=>setToast(''),2600)}
  const act=(id:string,action:'confirm'|'reject'|'assign'|'accept'|'start'|'claim'|'request'|'pass'|'fail',reason?:string,evidencePreview?:string,selectedContractorId?:string)=>{try{setStore(s=>transition(s,id,role,action,reason,evidencePreview,persona.id,persona.name,selectedContractorId));flash(action==='pass'?'Verified closed. The public ledger has been updated.':action==='fail'?'Verification failed. Issue reopened for repair.':action==='confirm'?'Fault confirmed by an independent verifier.':action==='reject'?'Report marked unconfirmed with a reason.':action==='claim'?'Repair claimed. Independent verification is now required.':action==='accept'?'Assignment accepted.':action==='start'?'Work marked in progress.':action==='request'?'Independent verification started.':action==='assign'?'Assigned to selected contractor.':'Action recorded.')}catch(e){flash(e instanceof Error?e.message:'Action could not be completed.')}}
  const saveLocationCorrection=()=>{if(!locationIssueId||!correctedLocation)return;try{setStore(s=>correctIssueLocation(s,locationIssueId,role,correctedLocation.lat,correctedLocation.lng,locationReason,persona.name??'Meera Nair',correctedAssetId));setModal(null);setLocationIssueId(null);setCorrectedLocation(null);setCorrectedAssetId('');setLocationReason('');flash('Location and asset correction recorded in the issue timeline and audit log.')}catch(e){flash(e instanceof Error?e.message:'Location correction could not be saved.')}}
  const openIssue=(id:string)=>{setPage('Issues');setActiveIssue(id);setMenuOpen(false)}
  const nav=(next:Page)=>{if(!allowedPages.includes(next))return;setPage(next);setActiveIssue(null);setMenuOpen(false)}
  const report=(asset:Asset|null,title:string,description:string,evidencePreview:string|undefined,location:ConfirmedLocation,unregisteredType?:string)=>{const id=`NR-${new Date().getFullYear()}-${String(Math.max(0,...store.issues.map(i=>Number(i.id.split('-').at(-1))||0))+1).padStart(4,'0')}`;const created:Issue={id,assetId:asset?.id,captureLat:location.lat,captureLng:location.lng,issueType:asset?.category??unregisteredType??'Other public asset',title,description,status:'Under verification',reporter:persona.name??'Asha Rao',reporterId:persona.id??'demo-citizen-asha',openedAt:new Date().toISOString(),dueAt:new Date(Date.now()+3*86400000).toISOString(),evidence:evidencePreview?2:1,evidencePreview,severity:'Medium',history:[{label:'Report received',actor:'Citizen',time:new Date().toISOString(),note:evidencePreview?'Photo evidence compressed and saved on this device':'Demo evidence recorded locally'},{label:'Location confirmed',actor:'Citizen',time:new Date().toISOString(),note:`Citizen-confirmed point · ${location.lat.toFixed(5)}, ${location.lng.toFixed(5)}`},...(!asset?[{label:'Unregistered asset observation',actor:'System',time:new Date().toISOString(),note:'No matching registered asset selected'}]:[])]};setStore(s=>addAudit({...s,issues:[created,...s.issues]},'Citizen','Report submitted',id,undefined,'Under verification'));localStorage.removeItem('noro-report-draft-v1');setPage('Issues');setActiveIssue(id);setModal(null);flash(`Report ${id} received. It will be reviewed before assignment.`)}

  return <div className="app-shell">
    {!online&&<div className="offline-banner"><span className="offline-dot"/> Offline · your draft stays on this device and sync is unavailable in demo mode</div>}
    <aside className={`sidebar ${menuOpen?'sidebar-open':''}`}>
      <div className="side-head"><button className="brand-button" onClick={()=>nav('Overview')} aria-label="Noro home"><Brand/></button><button className="icon-btn mobile-close" onClick={()=>setMenuOpen(false)} aria-label="Close navigation"><X size={18}/></button></div>
      <div className="ward-switch" role="status" aria-label="Current ward workspace"><span className="ward-icon"><MapPin size={15}/></span><span className="ward-copy"><small>WORKSPACE</small><b>Noro Demo Ward</b></span><ChevronDown size={15}/></div>
      <div className="nav-label">WORKSPACE</div><nav className="main-nav" aria-label="Main navigation">
        <NavItem icon={<Home/>} label={role==='Contractor'?'My work':role==='Verifier'?'Verification queue':role==='Citizen'?'Home':'Manager overview'} active={page==='Overview'} onClick={()=>nav('Overview')}/>
        <NavItem icon={<Activity/>} label={role==='Citizen'?'My reports':role==='Contractor'?'Assigned jobs':role==='Verifier'?'Checks & history':'Needs attention'} count={metrics.open} active={page==='Issues'} onClick={()=>nav('Issues')}/>
        {allowedPages.includes('Assets')&&<NavItem icon={<Bolt/>} label="Asset passports" count={store.assets.length} active={page==='Assets'} onClick={()=>nav('Assets')}/>}
        <NavItem icon={<Bell/>} label="Notifications" count={roleNotifications(store,role,persona.id).length} active={page==='Notifications'} onClick={()=>nav('Notifications')}/>
        <div className="nav-label nav-gap">TRANSPARENCY</div>
        {allowedPages.includes('Public ledger')&&<NavItem icon={<Radio/>} label="Public ledger" active={page==='Public ledger'} onClick={()=>nav('Public ledger')}/>}
        {allowedPages.includes('Audit trail')&&<NavItem icon={<ClipboardCheck/>} label="Audit trail" active={page==='Audit trail'} onClick={()=>nav('Audit trail')}/>}
      </nav>
      <div className="sidebar-bottom"><div className="demo-note"><span className="demo-note-icon"><Sparkles size={15}/></span><div><b>Demo environment</b><p>Fictional ward data · Local mode</p></div><span className="demo-dot"/></div><button className="nav-item" onClick={()=>nav('About Noro')}><CircleHelp size={17}/><span>About Noro</span></button>
        <div className="profile-row"><div className="avatar avatar-forest">{initials(persona.name??role)}</div><div className="profile-info"><b>{persona.name??role}</b><small>DEMO PERSONA · {persona.sub??role+' workspace'}</small></div></div>
      </div>
    </aside>
    {menuOpen&&<button className="scrim" aria-label="Close navigation" onClick={()=>setMenuOpen(false)}/>}
    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="icon-btn mobile-menu" onClick={()=>setMenuOpen(true)} aria-label="Open navigation"><Menu size={19}/></button><span className="crumb">Noro Demo Ward</span><span className="crumb-sep">/</span><span className="crumb-current">{page}</span></div><div className="topbar-right"><span className="demo-pill"><span/>DEMO / TEST</span><span className="simulated-pill">SIMULATED</span><button className="signout-button" onClick={()=>{sessionStorage.removeItem('noro-demo-identity');sessionStorage.removeItem('noro-mode');location.assign('/signin')}}>Sign out</button></div></header>
      <div className="content-wrap">
        {page==='Overview'&&<Overview role={role} store={{...store,issues:roleIssues}} metrics={metrics} onNavigate={nav} onReport={()=>setModal('report')} onOpen={openIssue} onLogin={()=>location.assign('/signin')}/>}
        {page==='Issues'&&(issue?<IssueDetail issue={issue} asset={assetFor(store,issue)} store={store} role={role} onBack={()=>setActiveIssue(null)} onAction={act} onEditLocation={()=>{setLocationIssueId(issue.id);setCorrectedLocation({lat:issue.locationLat??issue.captureLat??assetFor(store,issue).lat??12.9718,lng:issue.locationLng??issue.captureLng??assetFor(store,issue).lng??77.5942});setCorrectedAssetId(issue.assetId??'');setLocationReason('');setModal('location')}}/>:<IssuesPage issues={visibleIssues} store={store} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} role={role} onOpen={openIssue} onReport={()=>setModal('report')}/>)}
        {page==='Assets'&&<AssetsPage store={role==='Contractor'?{...store,assets:[]}:store} onIssue={openIssue} onReport={()=>setModal('report')} canReport={role==='Citizen'}/>}
        {page==='Notifications'&&<NotificationsPage notices={roleNotifications(store,role,persona.id)} onOpen={openIssue}/>}
        {page==='Public ledger'&&<Ledger store={store} metrics={metrics} onOpen={openIssue} onIssuePage={()=>nav('Issues')}/>}
        {page==='Audit trail'&&<AuditPage store={store} canReset={role!=='Public'} onReset={()=>{localStorage.removeItem('noro-demo-store-v1');setStore(initialStore);flash('Demo data reset to its original state.')}}/>}
        {page==='About Noro'&&<About/>}
      </div>
      <footer className="footer"><span>© 2026 Noro Civic Accountability Network</span><span><span className="footer-live"/>Demo environment <i/> All figures are fictional</span></footer>
    </main>
    {modal==='report'&&<ReportModal assets={store.assets} issues={store.issues} onClose={()=>setModal(null)} onSubmit={report}/>}
    {modal==='location'&&locationIssueId&&<div className="modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setModal(null)}><section className="modal location-correction-modal" role="dialog" aria-modal="true" aria-labelledby="location-correction-title"><div className="modal-head"><div><span className="card-kicker">MANAGER ACTION · AUDITABLE</span><h2 id="location-correction-title">Correct reported location</h2></div><button className="icon-btn" aria-label="Close dialog" onClick={()=>setModal(null)}>×</button></div><div className="location-origin"><b>Citizen-selected point</b><span>{(store.issues.find(i=>i.id===locationIssueId)?.captureLat??assetFor(store,store.issues.find(i=>i.id===locationIssueId)! ).lat)?.toFixed(5)}, {(store.issues.find(i=>i.id===locationIssueId)?.captureLng??assetFor(store,store.issues.find(i=>i.id===locationIssueId)! ).lng)?.toFixed(5)}</span></div><LocationPicker key={locationIssueId} assets={store.assets} initialLocation={correctedLocation??undefined} onChange={setCorrectedLocation}/><label className="form-label correction-asset-choice">Nearby asset<select value={correctedAssetId} onChange={e=>setCorrectedAssetId(e.currentTarget.value)}><option value="">Unregistered asset observation</option>{correctedLocation&&nearbyAssets(store.assets,correctedLocation,500).map(({asset:nearby})=><option value={nearby.id} key={nearby.id}>{nearby.id} · {nearby.name}</option>)}</select></label><label className="form-label correction-reason">Reason for correction<textarea value={locationReason} onInput={e=>setLocationReason(e.currentTarget.value)} rows={2} placeholder="Explain why the reported point needs correction"/></label><p className="privacy-note">The original point stays in the record. Your confirmed point, identity, reason, and time will be added to the timeline and audit log.</p><div className="modal-foot"><button className="button-secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button-primary" disabled={!correctedLocation||!locationReason.trim()} onClick={saveLocationCorrection}>Save correction</button></div></section></div>}

    {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/>{toast}</div>}
  </div>
}

export default function App(){
  const path=window.location.pathname
  if(path==='/')return <Landing/>
  if(path==='/signin'||path==='/signup')return <AuthPage mode={path==='/signup'?'signup':'signin'}/>
  if(path==='/demo')return <DemoAccess/>
  if(path.startsWith('/account/'))return <ProductionAccount role={decodeURIComponent(path.split('/')[2]??'member')}/> 
  if(path==='/public/map'||path==='/map'||path==='/public/ledger'||path==='/public-ledger'||path==='/assets')return <PublicExplorer initialTab={path==='/public/ledger'||path==='/public-ledger'?'ledger':path==='/assets'?'assets':'map'}/>
  if(path.startsWith('/workspace/')){
    const raw=decodeURIComponent(path.split('/')[2]??'Public')
    const role=(['Citizen','Manager','Contractor','Verifier','Public'] as Role[]).find(x=>x.toLowerCase()===raw.toLowerCase())??'Public'
    const identity=(()=>{try{return JSON.parse(sessionStorage.getItem('noro-demo-identity')??'null') as {role?:string;id?:string}|null}catch{return null}})()
    if(!identity||identity.role!==role){location.replace('/demo');return <DemoAccess/>}
    if(role==='Public')return <PublicExplorer initialTab='ledger'/>
    return <WorkspaceApp initialRole={role}/> 
  }
  window.history.replaceState({},'', '/')
  return <Landing/>
}

type Notice={id:string;issueId:string;title:string;detail:string;time:string}
function roleNotifications(store:Store,role:Role,personaId?:string):Notice[]{
  const notices:Notice[]=[]
  for(const issue of store.issues){
    const own=role==='Citizen'&&(issue.reporterId===personaId||issue.reporter==='Asha Rao'||issue.reporter==='Asha R.')
    const assigned=role==='Contractor'&&(issue.assigneeId===personaId||issue.assigneeId==='demo-contractor-imran')
    if(role==='Manager')for(const event of issue.history){if(event.label==='Report received')notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'New report received',detail:`${issue.id} · ${issue.title}`,time:event.time});if(event.label.includes('Repair claimed'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Repair claimed · verification required',detail:`${issue.id} · ${issue.title}`,time:event.time});if(event.label.includes('reopened'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Verification failed · issue reopened',detail:`${issue.id} · ${issue.title}`,time:event.time})}
    if(own)for(const event of issue.history){if(event.label==='Report received')notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Report received',detail:`${issue.id} · ${issue.title}`,time:event.time});else if(event.label.includes('Manager validated'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Report validated',detail:`${issue.id} is ready for assignment.`,time:event.time});else if(event.label.includes('Repair claimed'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Repair claimed',detail:'An independent check is still required before closure.',time:event.time});else if(event.label.includes('Verified')&&event.label.includes('closed'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Repair independently verified',detail:`${issue.id} is now verified closed.`,time:event.time});else if(event.label.includes('reopened'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Issue reopened after verification',detail:`${issue.id} needs another repair attempt.`,time:event.time})}
    if(assigned)for(const event of issue.history){if(event.label==='Contractor assigned'||event.label.includes('Assigned to repair team')||event.label.includes('Assigned to officer'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'New assignment',detail:`${issue.id} · ${issue.title}`,time:event.time});else if(event.label.includes('reopened'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Repair follow-up required',detail:`${issue.id} was reopened by independent verification.`,time:event.time});else if(event.label.includes('Verified')&&event.label.includes('closed'))notices.push({id:`${issue.id}-${event.time}`,issueId:issue.id,title:'Repair verified closed',detail:`${issue.id} passed an independent check.`,time:event.time})}
    if(role==='Verifier'&&issue.status==='Verification pending')notices.push({id:`${issue.id}-pending`,issueId:issue.id,title:'Verification task waiting',detail:`${issue.id} · ${issue.title}`,time:issue.history.at(-1)?.time??issue.openedAt})
    if((role==='Manager'||assigned||role==='Verifier')&&!['Verified closed','Cancelled','Duplicate'].includes(issue.status)&&new Date(issue.dueAt).getTime()-Date.now()<86400000)notices.push({id:`${issue.id}-due-${role}`,issueId:issue.id,title:'Due soon or overdue',detail:`${issue.id} · proposed SLA ${fmt(issue.dueAt)}`,time:issue.dueAt})
  }
  return notices.sort((a,b)=>b.time.localeCompare(a.time)).slice(0,40)
}
function NotificationsPage({notices,onOpen}:{notices:Notice[];onOpen:(id:string)=>void}){return <><div className="page-intro page-intro-compact"><div><div className="eyebrow"><span className="eyebrow-line"/>ROLE-SCOPED UPDATES</div><h1>Notifications</h1><p>Updates are derived from the issue timeline in this browser’s demo workspace.</p></div><span className="demo-pill"><span/>DEMO</span></div><section className="notification-feed" aria-label="Notifications">{notices.length?notices.map(item=><button className="notification-row" key={item.id} onClick={()=>onOpen(item.issueId)}><span className="notification-mark"><Bell size={16}/></span><span className="notification-copy"><b>{item.title}</b><small>{item.detail}</small></span><time>{new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(item.time))}</time><ArrowRight size={15}/></button>):<div className="empty-state"><CheckCircle2/><b>You’re all caught up</b><span>New role-specific workflow updates will appear here.</span></div>}</section></>}

function NavItem({icon,label,count,active,onClick}:{icon:ComponentChildren;label:string;count?:number;active:boolean;onClick:()=>void}){return <button className={`nav-item ${active?'nav-active':''}`} onClick={onClick}>{icon}<span>{label}</span>{count!==undefined&&<span className="nav-count">{count}</span>}</button>}

function Overview({role,store,metrics,onNavigate,onReport,onOpen,onLogin}:{role:Role;store:Store;metrics:{assets:number;open:number;claimed:number;verified:number;reopened:number;pending:number};onNavigate:(p:Page)=>void;onReport:()=>void;onOpen:(id:string)=>void;onLogin:()=>void}){
  const [showAll,setShowAll]=useState(false);const isPublic=role==='Public';const attention=store.issues.filter(i=>!['Verified closed','Cancelled','Duplicate'].includes(i.status)).slice(0,4);const focus=store.issues.find(i=>i.id==='NR-2026-0042')??store.issues[0]
  return <>
    <div className="page-intro"><div><div className="eyebrow"><span className="eyebrow-line"/>{isPublic?'PUBLIC ACCOUNTABILITY':'WARD OPERATIONS'}<span className="eyebrow-dot">·</span>NORO DEMO WARD</div><h1>{isPublic?'A repair claimed. A repair verified.':'Good morning, '+(role==='Manager'?'Meera Nair':role==='Citizen'?'Asha':role==='Contractor'?'Imran':role==='Verifier'?'Ravi':'there')+'.'}</h1><p>{isPublic?'See the difference independent verification makes across this fictional ward.':role==='Manager'?'Here’s what needs your attention across the ward today.':role==='Contractor'?'Your field work, clear next steps, and a fair record of every fix.':role==='Verifier'?'Independent checks waiting for a careful second look.':'Follow a public asset from first report to an independently checked outcome.'}</p></div><div className="intro-actions">{isPublic?<button className="button-secondary" onClick={onLogin}>Enter demo workspace <ArrowRight size={16}/></button>:role==='Citizen'?<button className="button-primary" onClick={onReport}><Plus size={17}/> Report an issue</button>:null}</div></div>
    <div className="accountability-banner"><div className="banner-left"><div className="banner-icon"><ShieldCheck size={20}/></div><div><strong>A repair is not complete when it’s claimed.</strong><span>Only an independent check can close the loop.</span></div></div><div className="banner-flow"><div className="flow-step flow-done"><span><Check size={13}/></span><b>Repair claimed</b></div><div className="flow-line"/><div className="flow-step flow-current"><span><Clock3 size={14}/></span><b>Verification pending</b></div><div className="flow-line flow-line-muted"/><div className="flow-step flow-muted"><span><Check size={13}/></span><b>Verified closed</b></div></div><button className="banner-arrow" aria-label="View accountability ledger" onClick={()=>onNavigate('Public ledger')}><ArrowRight size={18}/></button></div>
    <div className="section-title-row"><div><h2>Ward at a glance</h2><span className="section-caption">A live view of the demo workflow</span></div><button className="text-link" onClick={()=>onNavigate('Public ledger')}>View public ledger <ArrowRight size={15}/></button></div>
    <div className="metric-grid">
      <Metric label="Assets in registry" value={metrics.assets} icon={<Bolt/>} detail="Mixed civic assets · demo inventory" trend="Ward scope" tone="neutral" onClick={()=>onNavigate('Assets')}/>
      <Metric label="Open issues" value={metrics.open} icon={<Activity/>} detail={`${metrics.reopened} reopened · same issue history`} trend="Needs action" tone="sand" onClick={()=>onNavigate('Issues')}/>
      <Metric label="Repair claims" value={metrics.claimed} icon={<Clock3/>} detail={`${metrics.pending} awaiting independent check`} trend="Not yet verified" tone="amber" onClick={()=>onNavigate('Issues')}/>
      <Metric label="Verified closed" value={metrics.verified} icon={<BadgeCheck/>} detail="Independent checks passed" trend="Two-key closure" tone="green" onClick={()=>onNavigate('Public ledger')}/>
    </div>
    <div className="content-grid"><section className="card attention-card"><div className="card-heading"><div><span className="card-kicker">PRIORITY QUEUE</span><h3>{role==='Verifier'?'Verification queue':role==='Contractor'?'Assigned field work':isPublic?'Recent public issues':'Needs your attention'}</h3></div></div><div className="attention-list">{attention.slice(0,showAll?4:3).map((item,index)=><button className="attention-row" key={item.id} onClick={()=>onOpen(item.id)}><span className={`priority-mark priority-${item.severity.toLowerCase()}`}>{index===0?<Bolt size={15}/>:<MapPin size={15}/>}</span><span className="attention-main"><b>{item.title}</b><small>{assetFor(store,item).id} <i/> {agoText(item.openedAt)}</small></span><Status value={item.status}/><ArrowRight className="row-arrow" size={15}/></button>)}{!attention.length&&<div className="empty-state"><CheckCircle2/><b>Nothing needs attention</b><span>Your queue is clear for now.</span></div>}</div><div className="card-foot"><button className="text-link" onClick={()=>showAll?onNavigate('Issues'):setShowAll(true)}>{showAll?'Open issue workspace':'View all issues'} <ArrowRight size={14}/></button><span className="queue-note"><span/> Updated just now</span></div></section>
    <section className="card focus-card"><div className="card-heading"><div><span className="card-kicker">THE TWO-KEY CHECK</span><h3>A claim is only the first key.</h3></div><span className="focus-icon"><ShieldCheck size={18}/></span></div><div className="focus-asset"><div className="lamp-illustration"><div className="lamp-head"/><div className="lamp-pole"/><div className="lamp-base"/><span className="lamp-glow"/></div><div className="focus-asset-info"><span className="asset-tag">{assetFor(store,focus).category?.toUpperCase()??'PUBLIC ASSET'} · WARD 12</span><b>{assetFor(store,focus).id}</b><small>{assetFor(store,focus).location}</small></div></div><div className="focus-status"><span className="focus-status-icon"><Clock3 size={15}/></span><div><b>{focus.status==='Verified closed'?'Verified closed':focus.status==='Reopened'?'Reopened for follow-up':focus.status==='Repair claimed'?'Repair claimed':focus.status}</b><small>{focus.status==='Verified closed'?'Independent check passed':focus.status==='Reopened'?'The failed check returned this issue for repair':focus.status==='Repair claimed'?'Independent verification is next':focus.status==='Verification pending'?'Independent verifier is checking the repair':'Current issue state'}</small></div><Status value={focus.status}/></div><button className="focus-link" onClick={()=>onOpen(focus.id)}>Open issue timeline <ArrowRight size={15}/></button></section></div>
    <div className="lower-grid"><section className="card map-card"><div className="card-heading"><div><span className="card-kicker">ASSET MAP</span><h3>Public assets across the demo ward</h3></div><button className="text-link" onClick={()=>onNavigate('Assets')}>Full registry <ArrowRight size={14}/></button></div><CivicMap assets={store.assets} issues={store.issues} store={store} onSelect={item=>'assetId' in item?onOpen(item.id):onNavigate('Assets')}/><div className="map-legend"><span><i className="legend-dot dot-open"/>Open issue</span><span><i className="legend-dot dot-claimed"/>Claimed</span><span><i className="legend-dot dot-verified"/>Verified</span><span className="map-caption">Approximate demo locations</span></div></section><section className="card lifecycle-card"><div className="card-heading"><div><span className="card-kicker">THE ACCOUNTABILITY LOOP</span><h3>One issue. A complete record.</h3></div></div><div className="lifecycle">{[['01','Observe','A resident reports an asset fault'],['02','Verify','A different person confirms it'],['03','Assign','An accountable owner accepts'],['04','Repair','Crew records work and claims'],['05','Check','Independent evidence decides'],['06','Publish','Outcome enters public ledger']].map(([num,title,body],i)=><div className={`life-step ${i<3?'life-complete':''}`} key={num}><span className="life-num">{i<3?<Check size={12}/>:num}</span><div><b>{title}</b><small>{body}</small></div>{i<5&&<span className="life-connector"/>}</div>)}</div></section></div>
    <div className="honesty-note"><ShieldCheck size={15}/><span><b>DEMO DATA</b> · Fictional assets and workflows for demonstration only. This is not live government data.</span><button onClick={()=>onNavigate('About Noro')}>About the model <ArrowRight size={13}/></button></div>
  </>
}

function Metric({label,value,icon,detail,trend,tone,onClick}:{label:string;value:number;icon:ComponentChildren;detail:string;trend:string;tone:string;onClick:()=>void}){return <button className={`metric-card metric-${tone}`} onClick={onClick}><div className="metric-top"><span>{label}</span><span className="metric-icon">{icon}</span></div><div className="metric-value">{String(value).padStart(2,'0')}</div><div className="metric-bottom"><span>{detail}</span><span className="metric-trend">{trend}</span></div></button>}


function IssuesPage({issues,store,query,setQuery,filter,setFilter,role,onOpen,onReport}:{issues:Issue[];store:Store;query:string;setQuery:(v:string)=>void;filter:string;setFilter:(v:string)=>void;role:Role;onOpen:(id:string)=>void;onReport:()=>void}){const statuses=['All statuses','Under verification','Verified','Assigned','In progress','Repair claimed','Verification pending','Verified closed','Reopened'];return <><div className="page-intro page-intro-compact"><div><div className="eyebrow"><span className="eyebrow-line"/>ISSUE REGISTER</div><h1>{role==='Citizen'?'My reports':'Issue workspace'}</h1><p>Every issue stays linked to the asset, its repair claim, and the independent check.</p></div>{role==='Citizen'&&<button className="button-primary" onClick={onReport}><Plus size={16}/> Report issue</button>}</div><section className="card table-card"><div className="table-toolbar"><div className="search-box"><Search size={16}/><input aria-label="Search issues" placeholder="Search by issue, asset or ID…" value={query} onChange={e=>setQuery(e.currentTarget.value)}/>{query&&<button onClick={()=>setQuery('')} aria-label="Clear search"><X size={14}/></button>}</div><label className="filter-select"><Filter size={15}/><select value={filter} onChange={e=>setFilter(e.currentTarget.value)} aria-label="Filter issues by status">{statuses.map(s=><option key={s}>{s}</option>)}</select><ChevronDown size={14}/></label><span className="result-count">{issues.length} records</span></div><div className="issues-table-wrap"><table className="issues-table"><thead><tr><th>ISSUE / ASSET</th><th>STATUS</th><th>REPORTED</th><th>OWNER</th><th>SEVERITY</th><th/></tr></thead><tbody>{issues.map(item=>{const asset=assetFor(store,item);return <tr key={item.id} onClick={()=>onOpen(item.id)} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&onOpen(item.id)}><td><div className="issue-title-cell"><span className="issue-type-icon"><Bolt size={14}/></span><span><b>{item.title}</b><small>{asset.id} <i/> {item.id}</small></span></div></td><td><Status value={item.status}/></td><td><span className="date-cell">{fmt(item.openedAt)}</span><small className="sub-cell">{agoText(item.openedAt)}</small></td><td>{item.assignedTo?<span className="owner-chip"><span className="owner-avatar">WE</span>{item.assignedTo}</span>:<span className="unassigned">Unassigned</span>}</td><td><span className={`severity severity-${item.severity.toLowerCase()}`}><i/>{item.severity}</span></td><td><button className="icon-btn table-open" aria-label={`Open ${item.id}`} onClick={e=>{e.stopPropagation();onOpen(item.id)}}><ArrowRight size={15}/></button></td></tr>})}</tbody></table>{issues.length===0&&<div className="empty-state"><Search/><b>No issues match that search</b><span>Try another asset ID or status filter.</span></div>}</div><div className="table-foot"><span>DEMO DATA · SIMULATED WORKFLOW</span><span>Showing {issues.length} of {issues.length} records</span></div></section></>}

function IssueDetail({issue,asset,store,role,onBack,onAction,onEditLocation}:{issue:Issue;asset:Asset;store:Store;role:Role;onBack:()=>void;onEditLocation:()=>void;onAction:(id:string,action:'confirm'|'reject'|'assign'|'accept'|'start'|'claim'|'request'|'pass'|'fail',reason?:string,evidencePreview?:string,selectedContractorId?:string)=>void}){const canConfirm=(role==='Verifier'||role==='Manager')&&issue.status==='Under verification';const canAssign=role==='Manager'&&['Verified','Reopened'].includes(issue.status);const canAccept=role==='Contractor'&&issue.status==='Assigned';const canStart=role==='Contractor'&&issue.status==='Accepted';const canClaim=role==='Contractor'&&issue.status==='In progress';const canRequest=role==='Verifier'&&issue.status==='Repair claimed';const canVerify=role==='Verifier'&&issue.status==='Verification pending';const checklistLabels=issue.checklist??(asset.category==='Lighting'?['Light operates after dusk','Pole and equipment appear sound','Wiring appears safe','Correct asset and location','Issue resolved']:asset.category==='Public toilet'?['Facility accessible','Water available','Lighting functional','Plumbing functional','Sanitation condition acceptable','Issue resolved']:asset.category==='Footpath'?['Obstruction removed','Surface repaired','Safe passage maintained','Accessibility maintained','Location matches']:asset.category==='Drainage'?['Blockage removed','Water flow restored','Cover and structure safe','Issue resolved']:['Asset is functional','Location matches','Safety condition acceptable','Issue resolved']);const [checklist,setChecklist]=useState(checklistLabels.map(()=>false));const [conflictDeclared,setConflictDeclared]=useState(false);const [rejectionReason,setRejectionReason]=useState('');const [failureReason,setFailureReason]=useState('');const [verificationOutcome,setVerificationOutcome]=useState<'pass'|'fail'>('pass');const [verificationPhoto,setVerificationPhoto]=useState('');const [verificationPhotoError,setVerificationPhotoError]=useState('');const [contractorChoice,setContractorChoice]=useState('');const [assignmentReview,setAssignmentReview]=useState(false);const [repairNotes,setRepairNotes]=useState('');const [repairEvidence,setRepairEvidence]=useState('');const [repairPhotoError,setRepairPhotoError]=useState('');const requiredSpecialisation=issue.requiredSpecialisation??recommendedSpecialisation(asset,issue.title);const recommendedContractors=contractorDirectory.filter(c=>c.specialisations.includes(requiredSpecialisation));const visibleHistory=role==='Citizen'?issue.history.map(e=>({...e,actor:'Noro record',note:undefined})):issue.history;return <><button className="back-link" onClick={onBack}>← Back to issues</button><div className="detail-heading"><div><div className="eyebrow"><span className="eyebrow-line"/>ISSUE TIMELINE · {issue.id}</div><h1>{issue.title}</h1><p>{asset.id} <i/> {asset.name} <i/> {asset.ward}</p></div><Status value={issue.status}/></div><div className="detail-layout"><div><section className="card detail-summary"><div className="card-heading"><div><span className="card-kicker">CURRENT STATE</span><h3>{issue.status==='Verified closed'?'Independently verified and closed':issue.status==='Verification pending'?'The repair has been claimed. Verification is next.':issue.status}</h3></div><span className="summary-shield"><ShieldCheck size={20}/></span></div><p>{issue.description}</p>{issue.repairNotes&&<div className="repair-notes-record"><b>Repairer notes</b><span>{issue.repairNotes}</span>{issue.repairEvidencePreview&&<img className="evidence-photo" src={issue.repairEvidencePreview} alt="Contractor repair evidence"/>}</div>}<div className="summary-meta"><span><MapPin size={15}/>{issue.locationLat!==undefined?`${issue.locationLat.toFixed(5)}, ${issue.locationLng?.toFixed(5)} · ${issue.locationCorrection?'Manager corrected':'Citizen selected'}`:asset.location}</span><span><Clock3 size={15}/>Proposed SLA · {fmt(issue.dueAt)}</span>{role!=='Citizen'&&<span><Users size={15}/>{role==='Manager'?'Assigned contractor':'Contractor'} · {issue.assignedTo??'Not assigned'}</span>}</div>{role==='Manager'&&<div className="location-edit-row"><button className="button-secondary" onClick={onEditLocation}><MapPin size={15}/> Edit location</button>{issue.locationCorrection&&<span>Corrected by {issue.locationCorrection.actor} · {fmt(issue.locationCorrection.time)}</span>}</div>}{issue.locationCorrection&&<div className="location-audit-note"><b>Location corrected by manager</b><span>Original: {issue.locationCorrection.originalLat.toFixed(5)}, {issue.locationCorrection.originalLng.toFixed(5)}</span><span>Updated: {issue.locationCorrection.updatedLat.toFixed(5)}, {issue.locationCorrection.updatedLng.toFixed(5)}</span><span>Asset: {issue.locationCorrection.originalAssetId??'unregistered'} → {issue.locationCorrection.updatedAssetId??'unregistered'}</span><small>{issue.locationCorrection.reason} · {issue.locationCorrection.actor} · {fmt(issue.locationCorrection.time)}</small></div>}<div className="two-key-strip"><div className={issue.status==='Repair claimed'||issue.status==='Verification pending'||issue.status==='Verified closed'?'key-complete':''}><span>{issue.status==='Repair claimed'||issue.status==='Verification pending'||issue.status==='Verified closed'?<Check size={14}/>:<span>1</span>}</span><b>Repair claimed</b><small>Repairer submitted work evidence</small></div><div className="key-connector"/><div className={issue.status==='Verified closed'?'key-complete':issue.status==='Verification pending'?'key-current':''}><span>{issue.status==='Verified closed'?<Check size={14}/>:<span>2</span>}</span><b>Independent check</b><small>{issue.status==='Verified closed'?'Passed · closed':issue.status==='Verification pending'?'Required before closure':'Waiting for repair claim'}</small></div></div></section><section className="card timeline-card"><div className="card-heading"><div><span className="card-kicker">RECORD OF EVENTS</span><h3>Issue timeline</h3></div><span className="privacy-chip"><ShieldCheck size={12}/> Personal details hidden</span></div><div className="timeline">{visibleHistory.map((event,i)=><div className={`timeline-row ${i===issue.history.length-1?'timeline-latest':''}`} key={`${event.label}-${event.time}`}><div className="timeline-rail"><span className="timeline-point">{event.label.includes('Verified')||event.label.includes('passed')?<Check size={11}/>:<span/>}</span>{i<issue.history.length-1&&<i/>}</div><div className="timeline-copy"><b>{event.label}</b><small>{event.actor} <i/> {new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(event.time))}</small>{event.note&&<p>{event.note}</p>}</div></div>)}</div><div className="evidence-row"><div>{(issue.verificationEvidencePreviews?.at(-1)||issue.evidencePreview)?<img className="evidence-photo" src={issue.verificationEvidencePreviews?.at(-1)||issue.evidencePreview} alt={issue.verificationEvidencePreviews?.length?'Independent verifier evidence':'Citizen submitted evidence of the public asset'}/>:<span className="evidence-thumb"><Bolt size={18}/></span>}<span><b>{issue.evidence} evidence items</b><small>Timestamp and location attached · demo evidence</small></span></div><span className="evidence-badge"><CheckCircle2 size={13}/> Recorded</span></div></section></div><aside className="detail-aside"><section className="card action-card"><span className="card-kicker">ROLE ACTIONS</span><h3>{role} workspace</h3><p>Available actions depend on your role. Transitions are checked before they’re saved.</p>{canAssign&&<><div className="contractor-directory"><span className="card-kicker">CONTRACTOR DIRECTORY · RECOMMENDED</span><b>{requiredSpecialisation}</b><small>Eligible organisations for this issue</small>{recommendedContractors.map(c=><button type="button" key={c.id} className={contractorChoice===c.id?'contractor-choice selected':'contractor-choice'} onClick={()=>{setContractorChoice(c.id);setAssignmentReview(false)}}><span><b>{c.name}</b><small>{c.serviceCategories.join(' · ')}</small><small>{c.availability} · {c.operatingWard}{c.demoUserId?' · Demo account available':''}</small></span>{contractorChoice===c.id&&<Check size={15}/>}</button>)}</div>{assignmentReview&&contractorChoice&&<div className="assignment-review"><b>Review assignment</b><span>{contractorDirectory.find(c=>c.id===contractorChoice)?.name}</span><small>{asset.id} · {issue.title} · proposed SLA {fmt(issue.dueAt)}</small><p>The selected organization will receive this issue in its assigned work queue.</p></div>}<button className="button-primary full-button" disabled={!contractorChoice} onClick={()=>assignmentReview?onAction(issue.id,'assign',undefined,undefined,contractorChoice):setAssignmentReview(true)}>{assignmentReview?<><CheckCircle2 size={16}/> Confirm assignment</>:<><Users size={16}/> Review assignment</>}</button>{assignmentReview&&<button className="button-secondary full-button" onClick={()=>setAssignmentReview(false)}>Back to contractor list</button>}</>}{canAccept&&<button className="button-primary full-button" onClick={()=>onAction(issue.id,'accept')}><CheckCircle2 size={16}/> Accept assignment</button>}{canStart&&<button className="button-primary full-button" onClick={()=>onAction(issue.id,'start')}><Wrench size={16}/> Start work</button>}{canClaim&&<><label className="form-label">Repair notes<textarea value={repairNotes} onChange={e=>setRepairNotes(e.currentTarget.value)} rows={3} placeholder="Describe the repair completed"/></label><label className="upload-box repair-upload"><input type="file" accept="image/*" capture="environment" onChange={e=>{const file=e.currentTarget.files?.[0];if(file){setRepairPhotoError('');void compressEvidence(file).then(setRepairEvidence).catch(()=>setRepairPhotoError('This photo could not be prepared.'))}}}/><span className="upload-icon"><Plus size={18}/></span><span><b>{repairEvidence?'Repair evidence ready':'Add repair evidence'}</b><small>Photo required before the contractor claim</small></span></label>{repairPhotoError&&<div className="form-error">{repairPhotoError}</div>}<button className="button-primary full-button" disabled={!repairEvidence||!repairNotes.trim()} onClick={()=>onAction(issue.id,'claim',repairNotes,repairEvidence)}><CheckCircle2 size={16}/> Claim repair complete</button></>}{canConfirm&&<><div className="checklist-box"><b><ClipboardCheck size={15}/> {role==='Manager'?'Manager report review':'Fault verification'}</b><label><input type="checkbox" defaultChecked/> Confirm the correct public asset</label><label><input type="checkbox" defaultChecked/> Confirm the reported fault is observable</label>{role==='Verifier'&&<label><input type="checkbox" checked={conflictDeclared} onChange={e=>setConflictDeclared(e.currentTarget.checked)}/> I declare no conflict of interest</label>}<small>Review the citizen report and attached evidence before validating.</small></div><label className="upload-box verification-upload"><input type="file" accept="image/*" capture="environment" onChange={e=>{const file=e.currentTarget.files?.[0];if(file){setVerificationPhotoError('');void compressEvidence(file).then(setVerificationPhoto).catch(()=>{setVerificationPhoto('');setVerificationPhotoError('This photo could not be prepared. Try another image.')})}}}/><span className="upload-icon"><Plus size={18}/></span><span><b>{verificationPhoto?'Verification photo ready':'Add verifier photo'}</b><small>Captured on this device for the demo check</small></span></label>{verificationPhotoError&&<div className="form-error" role="alert">{verificationPhotoError}</div>}<button className="button-primary full-button" disabled={!verificationPhoto||(role==='Verifier'&&!conflictDeclared)} onClick={()=>onAction(issue.id,'confirm',undefined,verificationPhoto)}><Check size={16}/> {role==='Manager'?'Validate report':'Confirm fault'}</button><textarea className="reason-input" value={rejectionReason} onChange={e=>setRejectionReason(e.currentTarget.value)} rows={2} placeholder="Reason this fault could not be confirmed…"/><button className="button-outline-danger full-button" disabled={!rejectionReason.trim()||!verificationPhoto||(role==='Verifier'&&!conflictDeclared)} onClick={()=>onAction(issue.id,'reject',rejectionReason,verificationPhoto)}>Mark unconfirmed</button></>}{canRequest&&<><label className="checklist-declare"><input type="checkbox" checked={conflictDeclared} onChange={e=>setConflictDeclared(e.currentTarget.checked)}/> I declare no conflict of interest</label><button className="button-primary full-button" disabled={!conflictDeclared} onClick={()=>onAction(issue.id,'request')}><ClipboardCheck size={16}/> Start independent check</button></>}{canVerify&&<><div className="checklist-box"><b><ClipboardCheck size={15}/> Night verification checklist</b>{checklistLabels.map((label,index)=><label key={label}><input type="checkbox" checked={checklist[index]} onChange={e=>setChecklist(current=>current.map((value,i)=>i===index?e.currentTarget.checked:value))}/> {label}</label>)}<label><input type="checkbox" checked={conflictDeclared} onChange={e=>setConflictDeclared(e.currentTarget.checked)}/> I declare no conflict of interest</label><small>Mark each check complete, add a verifier photo, and declare conflicts before deciding.</small></div><label className="upload-box verification-upload"><input type="file" accept="image/*" capture="environment" onChange={e=>{const file=e.currentTarget.files?.[0];if(file){setVerificationPhotoError('');void compressEvidence(file).then(setVerificationPhoto).catch(()=>{setVerificationPhoto('');setVerificationPhotoError('This photo could not be prepared. Try another image.')})}}}/><span className="upload-icon"><Plus size={18}/></span><span><b>{verificationPhoto?'Verification photo ready':'Add verifier photo'}</b><small>Captured on this device for the demo check</small></span></label>{verificationPhotoError&&<div className="form-error" role="alert">{verificationPhotoError}</div>}<label className="form-label verification-outcome">Did the repair meet the service standard?<select value={verificationOutcome} onChange={e=>setVerificationOutcome(e.currentTarget.value as 'pass'|'fail')}><option value="pass">Yes, the repair passed</option><option value="fail">No, the fault remains</option></select></label>{verificationOutcome==='fail'&&<label className="form-label">What failed?<textarea value={failureReason} onChange={e=>setFailureReason(e.currentTarget.value)} rows={2} placeholder="Describe the failed check"/></label>}<button className="button-primary full-button" disabled={!checklist.every(Boolean)||!conflictDeclared||!verificationPhoto||verificationOutcome!=='pass'} onClick={()=>onAction(issue.id,'pass',undefined,verificationPhoto)}><Check size={16}/> Pass · verified closed</button><button className="button-outline-danger full-button" disabled={!checklist.every(Boolean)||!conflictDeclared||!verificationPhoto||verificationOutcome!=='fail'||!failureReason.trim()} onClick={()=>onAction(issue.id,'fail',failureReason,verificationPhoto)}>Fail · reopen issue</button></>}{!canConfirm&&!canAssign&&!canAccept&&!canStart&&!canClaim&&!canRequest&&!canVerify&&<div className="no-action"><ShieldCheck size={17}/><span>{issue.status==='Verification pending'?'Only a verifier can decide this check. The repairer cannot verify their own work.':'No action for this role at this step.'}</span></div>}<div className="separation-note"><ShieldCheck size={15}/><span><b>Role separation active</b><small>Reporter ≠ repairer ≠ verifier</small></span></div></section><section className="card asset-mini-card"><span className="card-kicker">ASSET PASSPORT</span><h3>{asset.id}</h3><span className="card-kicker">{asset.category}</span><div className="asset-detail-map"><CivicMap assets={asset.id==='UNREGISTERED_ASSET_OBSERVATION'?[]:[asset]} issues={[issue]} store={store} publicSafe onSelect={()=>{}}/></div>{role!=='Citizen'&&<RouteControl asset={asset}/>}<dl><div><dt>Ward</dt><dd>{asset.ward}</dd></div><div><dt>Responsible owner</dt><dd>{asset.owner}</dd></div><div><dt>Condition</dt><dd>{asset.condition}</dd></div><div><dt>Repeat failures · 90 days</dt><dd>{storeFailureCount(issue,asset.id)} <span className="proposed-tag">Demo</span></dd></div></dl></section></aside></div></>}
function storeFailureCount(issue:Issue,assetId:string){return issue.id.endsWith('0017')&&issue.assetId===assetId?'3':'1'}

function AssetsPage({store,onIssue,onReport,canReport}:{store:Store;onIssue:(id:string)=>void;onReport:()=>void;canReport:boolean}){const [search,setSearch]=useState('');const [selected,setSelected]=useState<Asset|null>(null);const [showAll,setShowAll]=useState(false);const assets=store.assets.filter(a=>`${a.id} ${a.name} ${a.location}`.toLowerCase().includes(search.toLowerCase()));const listedAssets=search.trim()||showAll?assets:assets.slice(0,24);if(selected)return <AssetPassport asset={selected} store={store} onBack={()=>setSelected(null)} onIssue={onIssue} onReport={onReport} canReport={canReport}/>;return <><div className="page-intro page-intro-compact"><div><div className="eyebrow"><span className="eyebrow-line"/>PUBLIC ASSET REGISTRY</div><h1>Asset passports</h1><p>The asset is the long-term record. Every issue and repair adds to its history.</p></div>{canReport&&<button className="button-primary" onClick={onReport}><Plus size={16}/> Report an issue</button>}</div><section className="asset-map-panel card"><div className="card-heading"><div><span className="card-kicker">WARD 12 · FICTIONAL INVENTORY</span><h3>Mixed assets across Noro Demo Ward</h3></div><span className="proposed-tag">Approximate demo locations</span></div><CivicMap assets={assets} issues={store.issues.filter(i=>assets.some(a=>a.id===i.assetId))} store={store} onSelect={item=>'status' in item?onIssue(item.id):setSelected(item)}/><div className="map-legend"><span><i className="legend-dot dot-open"/>Open issue</span><span><i className="legend-dot dot-claimed"/>Claimed / verification pending</span><span><i className="legend-dot dot-verified"/>No active issue</span><span className="map-caption">List view available below · demo coordinates</span></div></section><div className="asset-list-heading"><h2>Asset directory <span>{assets.length}</span></h2><div className="search-box"><Search size={15}/><input placeholder="Find an asset…" value={search} onChange={e=>setSearch(e.currentTarget.value)}/></div></div><div className="asset-grid">{listedAssets.map(a=>{const state=statusForAsset(store,a.id);const issue=store.issues.find(i=>i.assetId===a.id);return <button className="asset-card card" key={a.id} onClick={()=>setSelected(a)}><div className="asset-card-top"><span className="asset-symbol"><Bolt size={16}/></span><span className="proposed-tag">{a.id}</span><ArrowUpRight size={15}/></div><h3>{a.name}</h3><p><MapPin size={13}/>{a.location}</p><div className="asset-card-bottom"><Status value={state}/><small>{issue?'View asset passport':'No active issue'}</small></div><div className="asset-owner">Owner <b>{a.owner}</b></div></button>})}</div>{assets.length>24&&!showAll&&!search&&<div className="load-more">Showing 24 of {assets.length} assets <button onClick={()=>setShowAll(true)}>Show all assets</button></div>}</>}

function AssetPassport({asset,store,onBack,onIssue,onReport,canReport}:{asset:Asset;store:Store;onBack:()=>void;onIssue:(id:string)=>void;onReport:()=>void;canReport:boolean}){const history=store.issues.filter(i=>i.assetId===asset.id).sort((a,b)=>b.openedAt.localeCompare(a.openedAt));const lastClosed=history.find(i=>i.status==='Verified closed');const current=history.find(i=>!['Verified closed','Cancelled','Duplicate'].includes(i.status));const repeats=history.filter(i=>i.status==='Reopened').length;return <><button className="back-link" onClick={onBack}>← Back to asset directory</button><div className="detail-heading"><div><div className="eyebrow"><span className="eyebrow-line"/>DIGITAL ASSET PASSPORT · {asset.id}</div><h1>{asset.name}</h1><p>{asset.ward} <i/> {asset.location} <i/> Fictional demo coordinate</p></div>{canReport&&<button className="button-primary" onClick={onReport}><Plus size={15}/> Report issue</button>}</div><div className="passport-grid"><section className="card passport-main"><div className="passport-hero"><div className="passport-lamp"><Bolt size={32}/></div><div><span className="asset-tag">{asset.category?.toUpperCase()??'PUBLIC ASSET'} · DEMO INVENTORY</span><h2>{asset.id}</h2><p>{asset.location}</p></div><Status value={current?statusForAsset(store,asset.id):'No active issue'}/></div><div className="passport-fields"><div><small>RESPONSIBLE DEPARTMENT</small><b>{asset.department??asset.owner}</b><span>Service owner · proposed Accountability Map</span></div><div><small>SERVICE STANDARD</small><b>{asset.serviceStandard??'Serviceable and safe for public use'}</b><span><span className="proposed-tag">PROPOSED</span> · Version 1</span></div><div><small>CURRENT CONDITION</small><b>{current?.status==='Reopened'?'Needs attention':current?'Issue reported':asset.condition}</b><span>Last updated {fmt(current?.openedAt??new Date().toISOString())}</span></div><div><small>REPEAT FAILURES · 90 DAYS</small><b>{repeats}</b><span>{repeats>=3?'Root-cause review threshold met':'Demo history · not a live measure'}</span></div><div><small>LAST VERIFIED REPAIR</small><b>{lastClosed?'Independently checked':'No verified repair yet'}</b><span>{lastClosed?fmt(lastClosed.history.at(-1)!.time):'No completed record in demo history'}</span></div><div><small>WARD</small><b>{asset.ward}</b><span>Fictional ward · not municipal data</span></div></div></section><aside className="card passport-history"><span className="card-kicker">ASSET HISTORY</span><h3>Issues and repair record</h3>{history.length?history.map(item=><button className="passport-issue" key={item.id} onClick={()=>onIssue(item.id)}><span className="passport-issue-marker"><Bolt size={13}/></span><span><b>{item.title}</b><small>{item.id} · {fmt(item.openedAt)}</small></span><Status value={item.status}/></button>):<div className="passport-empty"><CheckCircle2/><b>No recorded issues</b><span>Use the report action to add a demo observation.</span></div>}<div className="passport-note"><ShieldCheck size={14}/><span>New events are linked to this asset’s history. A repair claim does not erase a previous issue.</span></div></aside></div><div className="honesty-note"><ShieldCheck size={15}/><span><b>ASSET PASSPORT</b> · The persistent record belongs to the asset; issues are events attached to it. All fields shown here are fictional demo content.</span></div></>}

function Ledger({store,metrics,onOpen,onIssuePage}:{store:Store;metrics:{assets:number;open:number;claimed:number;verified:number;reopened:number;pending:number};onOpen:(id:string)=>void;onIssuePage:()=>void}){const closed=metrics.verified;const claimed=metrics.claimed;const pct=claimed?Math.round(closed/claimed*100):0;return <><div className="page-intro page-intro-compact"><div><div className="eyebrow"><span className="eyebrow-line"/>PUBLIC ACCOUNTABILITY · Noro Demo Ward</div><h1>Claimed is not verified.</h1><p>The ledger shows both keys separately, so a completion claim can never quietly become a verified close.</p></div><span className="demo-pill ledger-badge"><span/>DEMO DATA</span></div><div className="ledger-callout"><ShieldCheck/><div><b>This is a fictional public ledger.</b><span>No live municipal system is connected. Proposed service standards are labelled and demo records are simulated.</span></div><span className="simulated-pill">SIMULATED</span></div><div className="ledger-summary-grid"><div className="ledger-stat"><small>TOTAL ASSETS</small><b>{metrics.assets}</b><span>Fictional demo inventory</span></div><div className="ledger-stat ledger-claimed"><small>REPAIR CLAIMS</small><b>{claimed}</b><span>Submitted claims, including later verified work</span></div><div className="ledger-stat ledger-pending"><small>AWAITING VERIFICATION</small><b>{metrics.pending}</b><span>Second key still required</span></div><div className="ledger-stat ledger-verified"><small>VERIFIED CLOSED</small><b>{closed}</b><span>Independent verifier passed</span></div></div><div className="ledger-main-grid"><section className="card ledger-chart-card"><div className="card-heading"><div><span className="card-kicker">THE CLOSURE GAP</span><h3>Claimed closures compared with verified closures</h3></div><span className="proposed-tag">DEMO COUNTS</span></div><div className="compare-bars"><div className="bar-row"><div><span className="bar-label">Repair claimed</span><b>{claimed}</b></div><div className="bar-track"><span className="bar-fill fill-amber" style={{width:`${Math.max(claimed*30,12)}%`}}/></div></div><div className="bar-row"><div><span className="bar-label">Verified closed</span><b>{closed}</b></div><div className="bar-track"><span className="bar-fill fill-green" style={{width:`${Math.max(closed*30,4)}%`}}/></div></div><div className="bar-legend"><span><i className="legend-dot dot-claimed"/>Claimed ({claimed})</span><span><i className="legend-dot dot-verified"/>Verified ({closed})</span></div><div className="gap-note"><ArrowDownRight size={17}/><span><b>{Math.max(0,claimed-closed)} still need independent verification</b><small>Completion claims do not count as verified closures.</small></span></div></div></section><section className="card ledger-ratio"><span className="card-kicker">VERIFICATION COVERAGE</span><div className="ratio-ring" style={{'--ratio':`${pct}%`} as CSSProperties}><div><b>{pct}%</b><small>verified</small></div></div><p>Of repair claims in this demo, this share has passed an independent check.</p><div className="ratio-mini"><span>Reopened <b>{metrics.reopened}</b></span><span>Open issues <b>{metrics.open}</b></span></div></section></div><section className="card ledger-records"><div className="card-heading"><div><span className="card-kicker">PUBLIC ISSUE RECORDS</span><h3>Recent outcomes</h3></div><button className="text-link" onClick={onIssuePage}>All issues <ArrowRight size={14}/></button></div>{store.issues.filter(i=>['Repair claimed','Verification pending','Verified closed','Reopened'].includes(i.status)).slice(0,6).map(i=><button className="ledger-record-row" key={i.id} onClick={()=>onOpen(i.id)}><span className="ledger-record-icon"><Bolt size={15}/></span><span className="ledger-record-name"><b>{i.title}</b><small>{assetFor(store,i).id} <i/> {i.id}</small></span><Status value={i.status}/><span className="ledger-record-date">{fmt(i.openedAt)}</span><ArrowRight size={14}/></button>)}</section><div className="honesty-note"><ShieldCheck size={15}/><span><b>METHOD</b> · Verified closures require an independent verifier with a passing checklist. Counts reflect seeded fictional demo records.</span></div></>}

function AuditPage({store,onReset,canReset}:{store:Store;onReset:()=>void;canReset:boolean}){return <><div className="page-intro page-intro-compact"><div><div className="eyebrow"><span className="eyebrow-line"/>GOVERNANCE · APPEND-ONLY DEMO LOG</div><h1>Audit trail</h1><p>Critical actions are recorded with actor role, entity, prior state, and new state.</p></div>{canReset&&<button className="button-secondary" onClick={onReset}>Reset demo data</button>}</div><div className="audit-integrity"><div className="audit-shield"><ShieldCheck size={20}/></div><div><b>Audit chain intact · {store.audit.length} recorded event{store.audit.length===1?'':'s'}</b><span>Every new action links to the previous entry. This browser demo uses a local checksum for illustration; production requires server-owned SHA-256 audit functions.</span></div><span className="integrity-pill"><CheckCircle2 size={14}/> DEMO CHECK</span></div><section className="card audit-table-card"><div className="card-heading"><div><span className="card-kicker">EVENT HISTORY</span><h3>Latest first</h3></div><span className="proposed-tag">PERSONAL DATA FILTERED</span></div><div className="audit-list">{[...store.audit].reverse().map(event=><div className="audit-event" key={event.id}><span className="audit-event-mark"><ClipboardCheck size={15}/></span><div className="audit-event-main"><b>{event.action}</b><span>{event.entity} {event.previous&&<><i className="state-arrow">{event.previous} → {event.next}</i></>}</span></div><div className="audit-event-actor"><span className="avatar avatar-tiny">{initials(event.role)}</span><span><b>{event.actor}</b><small>{event.role}</small></span></div><time>{new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(event.at))}</time><code>{event.hash}</code></div>)}</div></section></>}

function About(){return <><div className="page-intro page-intro-compact"><div><div className="eyebrow"><span className="eyebrow-line"/>THE NORO MODEL</div><h1>Civic accountability, made visible.</h1><p>Noro is a digital platform enabling the Civic Asset Accountability Network (CAAN) governance model.</p></div></div><section className="about-hero card"><div className="about-mark"><Brand/></div><div><span className="card-kicker">THE GOVERNANCE IDEA</span><h2>A repair is not complete because someone says “done.”</h2><p>Noro gives public assets a lasting record and keeps three roles apart: the person who reports, the team that repairs, and the independent verifier who confirms the outcome.</p></div></section><div className="about-cards"><section className="card"><span className="about-card-icon"><ShieldCheck size={18}/></span><h3>Two-key closure</h3><p>A repairer submits a completion claim. A separate verifier must pass a checklist before the same issue becomes verified closed.</p><span className="about-rule">CLAIMED ≠ VERIFIED</span></section><section className="card"><span className="about-card-icon"><Bolt size={18}/></span><h3>Asset-centred history</h3><p>Each public asset has a passport with its owner, condition, issues, repair events, and repeated failures.</p><span className="about-rule">ASSET → HISTORY</span></section><section className="card"><span className="about-card-icon"><Users size={18}/></span><h3>Ward Verification Panel</h3><p>A proposed ward level panel provides trained, rotating independent checks under a service charter and paper fallback.</p><span className="about-rule">A PROPOSED MODEL</span></section></div><section className="card about-steps"><div className="card-heading"><div><span className="card-kicker">THE FULL ACCOUNTABILITY LOOP</span><h3>Observe → verify → assign → commit → repair → independently verify → close → publish → analyse</h3></div></div><div className="about-steps-grid">{['Observe','Verify','Assign','Commit','Repair','Independently verify','Close','Publish','Analyse'].map((s,i)=><div key={s}><span>{String(i+1).padStart(2,'0')}</span><b>{s}</b></div>)}</div></section><div className="honesty-note"><ShieldCheck size={15}/><span><b>PROPOSED, NOT ADOPTED</b> · The Ward Verification Panel and service standards are a governance proposal. This demo does not imply municipal adoption or a government integration.</span></div></>}

async function compressEvidence(file:File):Promise<string>{const bitmap=await createImageBitmap(file);const scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d')?.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',0.72)}
